const express = require('express');
const session = require('express-session');
const argon2 = require('argon2');
const { RateLimiterMemory } = require('rate-limiter-flexible');

const PROD = process.env.NODE_ENV === 'production';
const SESSION_SECRET = process.env.SESSION_SECRET;
if (!SESSION_SECRET) throw new Error('SESSION_SECRET is required');

const app = express();
// Behind a reverse proxy, req.ip and secure cookies depend on this.
if (PROD) app.set('trust proxy', 1);
app.use(express.json({ limit: '10kb' }));

app.use(session({
  name: 'sid',
  secret: SESSION_SECRET,
  resave: false,
  saveUninitialized: false,
  // Default MemoryStore: single process only. Use connect-redis or similar in production.
  cookie: {
    httpOnly: true,
    sameSite: 'lax',
    secure: PROD,
    maxAge: 8 * 60 * 60 * 1000,
  },
}));

// Demo user store. Replace with a database.
const users = new Map(); // username -> { id, username, passwordHash }
let nextId = 1;

// Failed-attempt limiters. Replace with RateLimiterRedis when running more than one process.
const WINDOW_SECS = 15 * 60;
const MAX_FAILS_PER_USER_IP = 5;
const MAX_FAILS_PER_IP = 20;
const failsByUserIp = new RateLimiterMemory({
  keyPrefix: 'login_fail_user_ip',
  points: MAX_FAILS_PER_USER_IP,
  duration: WINDOW_SECS,
  blockDuration: WINDOW_SECS,
});
const failsByIp = new RateLimiterMemory({
  keyPrefix: 'login_fail_ip',
  points: MAX_FAILS_PER_IP,
  duration: WINDOW_SECS,
  blockDuration: WINDOW_SECS,
});

// Verified when the username is unknown, so response time does not reveal which usernames exist.
const dummyHash = argon2.hash('dummy-password');

const normalize = (username) => username.trim().toLowerCase();

function validCredentials(body) {
  const { username, password } = body ?? {};
  return typeof username === 'string' && typeof password === 'string'
    && username.trim().length >= 1 && username.length <= 64
    && password.length >= 8 && password.length <= 1024;
}

function tooMany(res, msBeforeNext) {
  const secs = Math.max(1, Math.ceil(msBeforeNext / 1000));
  res.set('Retry-After', String(secs));
  return res.status(429).json({ error: 'Too many failed attempts. Try again later.' });
}

function requireAuth(req, res, next) {
  if (!req.session.userId) return res.status(401).json({ error: 'Not authenticated' });
  next();
}

app.post('/register', async (req, res, next) => {
  try {
    if (!validCredentials(req.body)) {
      return res.status(400).json({ error: 'Username (1-64 chars) and password (8-1024 chars) required' });
    }
    const username = normalize(req.body.username);
    if (users.has(username)) return res.status(409).json({ error: 'Username taken' });

    const passwordHash = await argon2.hash(req.body.password, { type: argon2.argon2id });
    users.set(username, { id: nextId++, username, passwordHash });
    res.status(201).json({ username });
  } catch (err) {
    next(err);
  }
});

app.post('/login', async (req, res, next) => {
  try {
    const { username: rawUsername, password } = req.body ?? {};
    if (typeof rawUsername !== 'string' || typeof password !== 'string'
      || rawUsername.length > 64 || password.length > 1024) {
      return res.status(400).json({ error: 'Username and password required' });
    }
    const username = normalize(rawUsername);
    const ipKey = req.ip;
    const userIpKey = `${username}_${req.ip}`;

    // Reject before touching the password while either key is blocked.
    const [ipState, userIpState] = await Promise.all([
      failsByIp.get(ipKey),
      failsByUserIp.get(userIpKey),
    ]);
    if (ipState && ipState.consumedPoints > MAX_FAILS_PER_IP) {
      return tooMany(res, ipState.msBeforeNext);
    }
    if (userIpState && userIpState.consumedPoints > MAX_FAILS_PER_USER_IP) {
      return tooMany(res, userIpState.msBeforeNext);
    }

    const user = users.get(username);
    const ok = await argon2.verify(user ? user.passwordHash : await dummyHash, password);

    if (!user || !ok) {
      try {
        await Promise.all([failsByIp.consume(ipKey), failsByUserIp.consume(userIpKey)]);
      } catch (rejected) {
        if (rejected instanceof Error) throw rejected;
        return tooMany(res, rejected.msBeforeNext);
      }
      // Same message for unknown user and wrong password.
      return res.status(401).json({ error: 'Invalid username or password' });
    }

    await failsByUserIp.delete(userIpKey);

    // New session ID on login prevents session fixation.
    req.session.regenerate((err) => {
      if (err) return next(err);
      req.session.userId = user.id;
      req.session.username = user.username;
      req.session.save((saveErr) => {
        if (saveErr) return next(saveErr);
        res.json({ username: user.username });
      });
    });
  } catch (err) {
    next(err);
  }
});

app.post('/logout', (req, res, next) => {
  req.session.destroy((err) => {
    if (err) return next(err);
    res.clearCookie('sid');
    res.status(204).end();
  });
});

app.get('/me', requireAuth, (req, res) => {
  res.json({ id: req.session.userId, username: req.session.username });
});

app.use((err, req, res, next) => {
  console.error(err);
  res.status(500).json({ error: 'Internal server error' });
});

if (require.main === module) {
  const port = process.env.PORT || 3000;
  app.listen(port, () => console.log(`Listening on ${port}`));
}

module.exports = app;

